pragma solidity >=0.8.0;
contract EventIdxDyn {
    event Pair(string indexed sIdx, string sVal, bytes indexed bIdx, bytes bVal);
    string public lastS;
    bytes public lastB;
    function emitPair(string memory s, bytes memory b) external {
        lastS = s;
        lastB = b;
        emit Pair(s, s, b, b);
    }
    function emitPairTwice(string memory s1, bytes memory b1, string memory s2, bytes memory b2) external {
        lastS = s1;
        lastB = b1;
        emit Pair(s1, s1, b1, b1);
        lastS = s2;
        lastB = b2;
        emit Pair(s2, s2, b2, b2);
    }
    function getLast() external view returns (string memory, bytes memory) {
        return (lastS, lastB);
    }
}
